('question_count', '1600'),
('pdf_count', '13');
INSERT INTO `course_modules` (`id`, `title`, `level`, `target`, `chain`, `raw_json`) VALUES
('m01', '物质分类与化学用语', '必会', '能把陌生物质归类，能写化学式、化合价、方程式，这是后面所有题的入口。', '元素 -> 化合价 -> 化学式 -> 物质分类 -> 方程式 -> 守恒', '{"id":"m01","title":"物质分类与化学用语","target":"能把陌生物质归类，能写化学式、化合价、方程式，这是后面所有题的入口。","level":"必会","chain":"元素 -> 化合价 -> 化学式 -> 物质分类 -> 方程式 -> 守恒","essentials":["纯净物分单质和化合物，化合物再按氧化物、酸、碱、盐、有机物等识别。","化合价用于写化学式，正负化合价代数和为零。","化学方程式必须符合客观事实和质量守恒，配平后系数可用于计算。","离子符号既表示电荷，也表示离子个数和种类。"],"example":{"stem":"为什么 Na2CO3 既是盐，又能使酚酞变红？","answer":"Na2CO3 属于盐，因为由 Na+ 和 CO3^2- 构成；水溶液显碱性，是因为 CO3^2- 发生水解生成 OH-。分类和性质不是同一个维度。"},"traps":["盐不一定显中性。","含氧元素的化合物不一定都是氧化物，例如 H2SO4 不是氧化物。","有单质参加或生成的反应不一定都只是置换反应。"],"checkpoint":"看到一个物质，先问：由哪些微粒构成，属于哪类，能和哪类物质反应。"}'),
('m02', '物质的量与守恒计算', '必会', '能把质量、粒子数、体积、浓度互相转换，解决高考选择题和综合题的基础计算。', '化学方程式 -> 系数比例 -> n=m/M -> c=n/V -> 守恒法', '{"id":"m02","title":"物质的量与守恒计算","target":"能把质量、粒子数、体积、浓度互相转换，解决高考选择题和综合题的基础计算。","level":"必会","chain":"化学方程式 -> 系数比例 -> n=m/M -> c=n/V -> 守恒法","essentials":["物质的量 n 是宏观质量和微观粒子数之间的桥。","常用关系：n=m/M，N=nNA，c=n/V。","方程式系数表示物质的量比。","复杂计算优先找元素守恒、电荷守恒、电子守恒。"],"example":{"stem":"2 mol H2 完全燃烧最多生成多少 mol H2O？","answer":"2H2 + O2 = 2H2O，H2 和 H2O 的系数比为 2:2，即 1:1，所以生成 2 mol H2O。"},"traps":["气体摩尔体积要看温度和压强条件。","溶液体积用 L，不是 mL。","不要把质量比直接当成物质的量比。"],"checkpoint":"遇到计算题，先把已知量统一换成 n，再按方程式或守恒关系推进。"}'),
('m03', '离子反应与离子共存', '必会', '能写离子方程式，能判断离子能否大量共存，能做溶液推断。', '酸碱盐 -> 电离 -> 离子 -> 沉淀/气体/弱电解质 -> 离子方程式', '{"id":"m03","title":"离子反应与离子共存","target":"能写离子方程式，能判断离子能否大量共存，能做溶液推断。","level":"必会","chain":"酸碱盐 -> 电离 -> 离子 -> 沉淀/气体/弱电解质 -> 离子方程式","essentials":["强酸、强碱、可溶性盐在离子方程式中拆成离子。","沉淀、气体、水、弱酸、弱碱、氧化物一般不拆。","共存判断先看沉淀、气体、弱电解质，再看氧化还原、络合、双水解。","离子检验要考虑干扰离子和试剂顺序。"],"example":{"stem":"BaCl2 溶液为什么能检验 SO4^2-？","answer":"Ba2+ 与 SO4^2- 生成难溶 BaSO4 白色沉淀。检验时要排除 CO3^2-、SO3^2- 等也能与 Ba2+ 生成白色沉淀的干扰。"},"traps":["弱电解质不能拆成离子。","微溶物在反应物和生成物中的处理不同，要结合题目环境。","酸性或碱性条件会改变离子共存结论。"],"checkpoint":"判断离子题时，把所有可能发生的离子反应写出来。"}'),
('m04', '氧化还原与电子守恒', '必会', '能识别氧化剂、还原剂，能配平氧化还原，能处理电化学和滴定基础题。', '化合价升降 -> 电子转移 -> 氧化剂/还原剂 -> 电子守恒 -> 配平/计算', '{"id":"m04","title":"氧化还原与电子守恒","target":"能识别氧化剂、还原剂，能配平氧化还原，能处理电化学和滴定基础题。","level":"必会","chain":"化合价升降 -> 电子转移 -> 氧化剂/还原剂 -> 电子守恒 -> 配平/计算","essentials":["化合价升高是失电子，被氧化，作还原剂。","化合价降低是得电子，被还原，作氧化剂。","得失电子总数相等，是氧化还原配平和计算核心。","常见强氧化剂：Cl2、KMnO4、HNO3、浓 H2SO4、Fe3+ 等。"],"example":{"stem":"Fe2+ 与 Cl2 反应时谁是还原剂？","answer":"Fe2+ 被 Cl2 氧化为 Fe3+，化合价升高，失电子，所以 Fe2+ 是还原剂；Cl2 得电子变为 Cl-，是氧化剂。"},"traps":["有氧元素参加不一定是氧化还原反应。","同一种元素中间价态可能既有氧化性又有还原性。","酸碱环境会影响氧化还原产物。"],"checkpoint":"所有氧化还原题先标化合价，再数电子。"}'),
('m05', '元素化合物与无机推断', '必会', '能用颜色、沉淀、气体、特殊反应建立无机转化链。', '元素周期律 -> 元素性质 -> 典型物质 -> 特征现象 -> 转化链', '{"id":"m05","title":"元素化合物与无机推断","target":"能用颜色、沉淀、气体、特殊反应建立无机转化链。","level":"必会","chain":"元素周期律 -> 元素性质 -> 典型物质 -> 特征现象 -> 转化链","essentials":["金属重点掌握 Na、Al、Fe、Cu 及其化合物。","非金属重点掌握 Cl、S、N、Si、C 及其化合物。","无机推断常用证据：颜色、沉淀、气体、焰色、反应条件。","元素化合物题常与离子反应、氧化还原连考。"],"example":{"stem":"Fe2+ 和 Fe3+ 如何互相转化？","answer":"Fe2+ 可被 Cl2、KMnO4 等氧化为 Fe3+；Fe3+ 可被 Fe、Cu、I- 等还原为 Fe2+。这条转化链本质是氧化还原。"},"traps":["白色沉淀种类很多，不能只凭颜色定物质。","Al、Al2O3、Al(OH)3 都有两性特征。","硝酸通常表现强氧化性，和金属反应一般不放出 H2。"],"checkpoint":"推断题先抓强特征，再把特征写成反应关系。"}'),
('m06', '化学反应与能量', '常考', '能判断吸热放热，会读热化学方程式，会用盖斯定律做基础题。', '化学键 -> 断键/成键 -> 反应热 -> 热化学方程式 -> 能源应用', '{"id":"m06","title":"化学反应与能量","target":"能判断吸热放热，会读热化学方程式，会用盖斯定律做基础题。","level":"常考","chain":"化学键 -> 断键/成键 -> 反应热 -> 热化学方程式 -> 能源应用","essentials":["断键吸热，成键放热。","反应热与物质状态、方程式系数有关。","热化学方程式要注明状态。","盖斯定律本质是能量守恒，反应热可加减。"],"example":{"stem":"同一反应中生成液态水和气态水，反应热一样吗？","answer":"不一样。液态水能量低于气态水，生成液态水通常放热更多，所以反应热数值不同。"},"traps":["放热反应的 ΔH 为负。","方程式乘以 2，ΔH 也乘以 2。","反应热不是活化能。"],"checkpoint":"看热化学题时，同时看方程式系数、状态和 ΔH 正负。"}'),
('m07', '反应速率与化学平衡', '必会', '能区分快慢和限度，能判断平衡移动、转化率和平衡常数。', '可逆反应 -> 速率 -> 动态平衡 -> 条件改变 -> 平衡移动 -> 转化率', '{"id":"m07","title":"反应速率与化学平衡","target":"能区分快慢和限度，能判断平衡移动、转化率和平衡常数。","level":"必会","chain":"可逆反应 -> 速率 -> 动态平衡 -> 条件改变 -> 平衡移动 -> 转化率","essentials":["速率解决反应快慢，平衡解决反应限度。","催化剂改变速率，不改变平衡位置和平衡常数。","温度改变通常会改变平衡常数。","勒夏特列原理：平衡会向减弱改变的方向移动。"],"example":{"stem":"合成氨为什么高压有利？","answer":"N2 + 3H2 ⇌ 2NH3，气体物质的量从 4 变 2。增大压强，平衡向气体分子数减少方向移动，有利于 NH3 生成。"},"traps":["平衡移动不等于某物质浓度一定减小。","加入惰性气体是否影响平衡，要看恒容还是恒压。","K 只与温度有关，不随浓度和压强直接改变。"],"checkpoint":"遇到条件改变，分别判断速率、平衡方向、K、转化率。"}'),
('m08', '水溶液平衡与滴定', '常考', '能分析弱电解质、电离、水解、Ksp、pH 和滴定曲线。', '弱电解质 -> 电离平衡 -> 水解平衡 -> pH -> 滴定曲线/沉淀平衡', '{"id":"m08","title":"水溶液平衡与滴定","target":"能分析弱电解质、电离、水解、Ksp、pH 和滴定曲线。","level":"常考","chain":"弱电解质 -> 电离平衡 -> 水解平衡 -> pH -> 滴定曲线/沉淀平衡","essentials":["弱酸弱碱只部分电离，存在动态平衡。","盐类水解来自弱酸根或弱碱阳离子与水反应。","Ksp 用于判断沉淀生成、溶解和转化。","滴定曲线要看起点、突跃范围、等量点和终点。"],"example":{"stem":"CH3COONa 溶液为什么显碱性？","answer":"CH3COO- 是弱酸根，能与水反应生成 CH3COOH 和 OH-，使溶液显碱性。"},"traps":["酸式盐溶液不一定显酸性。","稀释弱酸时电离程度增大，但 H+ 浓度通常减小。","沉淀是否生成要看离子积 Q 与 Ksp。"],"checkpoint":"水溶液题要同时看电离、水解、沉淀溶解和电荷守恒。"}'),
('m09', '电化学', '常考', '能判断原电池、电解池的电极、电极反应、离子移动和产物。', '氧化还原 -> 电子转移 -> 电极反应 -> 离子移动 -> 电化学计算', '{"id":"m09","title":"电化学","target":"能判断原电池、电解池的电极、电极反应、离子移动和产物。","level":"常考","chain":"氧化还原 -> 电子转移 -> 电极反应 -> 离子移动 -> 电化学计算","essentials":["原电池负极发生氧化，正极发生还原。","电解池阳极发生氧化，阴极发生还原。","电子只在外电路移动，离子在溶液或盐桥中移动。","电化学计算仍用电子守恒。"],"example":{"stem":"锌铜原电池中锌为什么是负极？","answer":"锌更活泼，失电子生成 Zn2+，发生氧化反应；电子从锌经外电路流向铜电极。"},"traps":["正负极和阴阳极不能混用。","电解产物要看电极材料和离子放电顺序。","盐桥作用是维持电荷平衡，不是传导电子。"],"checkpoint":"电化学题先写氧化和还原半反应，再判断电极。"}'),
('m10', '有机化学基础', '必会', '能识别官能团，判断常见反应类型，完成简单推断和合成。', '碳骨架 -> 官能团 -> 性质 -> 反应类型 -> 官能团转化 -> 合成路线', '{"id":"m10","title":"有机化学基础","target":"能识别官能团，判断常见反应类型，完成简单推断和合成。","level":"必会","chain":"碳骨架 -> 官能团 -> 性质 -> 反应类型 -> 官能团转化 -> 合成路线","essentials":["烃看不饱和度，烃的衍生物看官能团。","常见反应：取代、加成、消去、氧化、还原、酯化、水解、加聚、缩聚。","同分异构先排碳骨架，再排官能团位置和类别。","合成题常用逆推：目标官能团从哪里来。"],"example":{"stem":"乙醇到乙酸经历了什么官能团变化？","answer":"乙醇含羟基，先氧化为乙醛中的醛基，再继续氧化为乙酸中的羧基。"},"traps":["能发生银镜反应的不只有普通醛。","苯环稳定，不等同于烯烃双键。","酯化反应和水解反应互为联系，要注意条件。"],"checkpoint":"有机题先圈官能团，再写反应类型。"}'),
('m11', '化学实验与证据推理', '必会', '能看懂装置功能、设计对照、分析误差和得出可靠结论。', '实验目的 -> 装置功能 -> 现象/数据 -> 干扰排除 -> 证据链 -> 结论', '{"id":"m11","title":"化学实验与证据推理","target":"能看懂装置功能、设计对照、分析误差和得出可靠结论。","level":"必会","chain":"实验目的 -> 装置功能 -> 现象/数据 -> 干扰排除 -> 证据链 -> 结论","essentials":["每个装置都要回答：制取、除杂、干燥、收集、检验还是尾气处理。","探究实验要控制变量，只改变研究因素。","定量实验要判断测量值偏大还是偏小。","结论必须由证据支持，不能只凭单一现象。"],"example":{"stem":"为什么气体实验常有尾气处理装置？","answer":"有些气体有毒、刺激性或污染环境，例如 Cl2、SO2、NO2，需要用合适试剂吸收，防止污染和安全风险。"},"traps":["洗气瓶进气方向通常长进短出。","干燥剂不能与被干燥气体反应。","滴定终点不一定等于等量点。"],"checkpoint":"看实验题时，把装置按功能标注，再看证据链是否闭合。"}'),
('m12', '工艺流程与综合题', '高考必练', '能把元素化合物、离子反应、氧化还原、平衡、实验和计算合并解题。', '原料 -> 预处理 -> 浸取/氧化还原 -> 除杂 -> 分离提纯 -> 产品/循环', '{"id":"m12","title":"工艺流程与综合题","target":"能把元素化合物、离子反应、氧化还原、平衡、实验和计算合并解题。","level":"高考必练","chain":"原料 -> 预处理 -> 浸取/氧化还原 -> 除杂 -> 分离提纯 -> 产品/循环","essentials":["先找目标元素和目标产物。","酸浸、碱浸、焙烧、氧化、还原都是为了让目标成分进入可处理状态。","调 pH 常用于分步沉淀除杂。","滤液、滤渣、循环物都要追踪元素去向。"],"example":{"stem":"流程题中为什么经常加入过量试剂？","answer":"过量试剂常用于保证目标离子完全沉淀或完全反应；后续必须有步骤除去过量试剂，否则会引入新杂质。"},"traps":["不要只看操作名称，要看元素去向。","除杂试剂过量后必须处理。","循环利用物通常能降低成本或减少污染。"],"checkpoint":"流程题每一步都标注：目标是什么，除掉了什么，留下了什么。"}');
INSERT INTO `knowledge_edges` (`source`, `relation`, `target`, `topic`, `use_text`, `raw_json`) VALUES
('原子结构', '质子数决定', '元素', '结构链', '判断同种元素、核素、周期表位置', '{"from":"原子结构","relation":"质子数决定","to":"元素","use":"判断同种元素、核素、周期表位置","topic":"结构链"}'),
('原子结构', '核外电子排布决定', '最外层电子', '结构链', '解释元素化学性质差异', '{"from":"原子结构","relation":"核外电子排布决定","to":"最外层电子","use":"解释元素化学性质差异","topic":"结构链"}'),
('最外层电子', '得失电子倾向形成', '化合价/离子', '表达链', '写化学式、判断离子形成', '{"from":"最外层电子","relation":"得失电子倾向形成","to":"化合价/离子","use":"写化学式、判断离子形成","topic":"表达链"}'),
('最外层电子', '周期性变化表现为', '元素周期律', '结构链', '比较元素性质', '{"from":"最外层电子","relation":"周期性变化表现为","to":"元素周期律","use":"比较元素性质","topic":"结构链"}'),
('元素周期律', '解释强弱', '金属性/非金属性', '结构链', '推断未知元素性质', '{"from":"元素周期律","relation":"解释强弱","to":"金属性/非金属性","use":"推断未知元素性质","topic":"结构链"}'),
('金属性/非金属性', '决定', '单质和化合物性质', '结构链', '预测氧化物、酸碱性和反应活性', '{"from":"金属性/非金属性","relation":"决定","to":"单质和化合物性质","use":"预测氧化物、酸碱性和反应活性","topic":"结构链"}'),
('化合价/离子', '正负价配平', '化学式', '表达链', '书写氧化物、酸碱盐化学式', '{"from":"化合价/离子","relation":"正负价配平","to":"化学式","use":"书写氧化物、酸碱盐化学式","topic":"表达链"}'),
('化学式', '物质变化写成', '化学方程式', '表达链', '表达反应事实', '{"from":"化学式","relation":"物质变化写成","to":"化学方程式","use":"表达反应事实","topic":"表达链"}'),
('化学方程式', '原子守恒要求', '配平', '表达链', '保证质量守恒', '{"from":"化学方程式","relation":"原子守恒要求","to":"配平","use":"保证质量守恒","topic":"表达链"}'),
('配平', '系数即比例', '质量守恒/物质的量计算', '定量链', '解决质量、物质的量、过量计算', '{"from":"配平","relation":"系数即比例","to":"质量守恒/物质的量计算","use":"解决质量、物质的量、过量计算","topic":"定量链"}'),
('单质和化合物性质', '按共性归类', '物质分类', '离子链', '选择鉴别试剂和预测通性', '{"from":"单质和化合物性质","relation":"按共性归类","to":"物质分类","use":"选择鉴别试剂和预测通性","topic":"离子链"}'),
('物质分类', '类别通性', '酸碱盐/氧化物/金属', '离子链', '判断反应类型', '{"from":"物质分类","relation":"类别通性","to":"酸碱盐/氧化物/金属","use":"判断反应类型","topic":"离子链"}'),
